function themeButton(){const dark=document.documentElement.dataset.theme==='dark';$('#theme').innerHTML=dark?icons.sun:icons.moon;$('#theme').setAttribute('aria-label',dark?'Attiva modalità chiara':'Attiva modalità scura');$('#theme').setAttribute('aria-pressed',String(dark))}
$('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('proofly-theme',document.documentElement.dataset.theme)}catch{}themeButton()};themeButton();
function math(root=document){renderMathInElement(root,{delimiters:[{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false}],throwOnError:true,strict:'ignore'})}
