const fmt=x=>{if(Math.abs(x)<1e-9)x=0;return Number(x.toFixed(3)).toLocaleString('it-IT')};
const texnum=x=>String(Number(x.toFixed(3)));
const eq=(m,q)=>`y=${texnum(m)}x${q>=0?'+':''}${texnum(q)}`;
