function home(){return `<div class="hero"><div class="eyebrow">Matematica · Fisica · Comprensione</div><h1>Le idee diventano chiare. <br><span>Un passo alla volta.</span></h1><p>Spiegazioni semplici, ragionamenti rigorosi.<br>Esplora, sperimenta e scopri il perché delle cose.</p><div class="searchbox">${icons.search}<input id="search" type="search" placeholder="Quale argomento vuoi capire?" aria-label="Cerca un argomento" aria-controls="results" autocomplete="off"><kbd>/</kbd></div><div class="chips"><a href="#lezione/due-punti">Retta per due punti</a><a href="#lezione/coefficiente-angolare">Pendenza</a><a href="#lezione/newton-2">Leggi di Newton</a></div><div id="results" aria-live="polite" class="hidden"></div></div><div class="container"><div class="section-heading"><div><h2>Da dove vuoi iniziare?</h2><p>Due percorsi. Un unico obiettivo: capire davvero.</p></div><span class="eyebrow">13 capitoli</span></div><div class="path-grid"><a class="path-card" href="#materia/matematica"><div class="path-art">${artMath}</div><div class="path-content"><span class="tag">Matematica · Geometria analitica</span><h3>La retta, da ogni punto di vista.</h3><p>Dalle coordinate alle equazioni. Costruisci rette, confronta direzioni e misura distanze.</p><div class="card-bottom"><span>10 capitoli · 10 laboratori · 30 esercizi</span><span class="arrow">↗</span></div></div></a><a class="path-card" href="#materia/fisica"><div class="path-art physics">${artPhysics}</div><div class="path-content"><span class="tag physics">Fisica · Meccanica classica</span><h3>Le tre leggi che spiegano il moto.</h3><p>Inerzia, forze e interazioni. Dai fenomeni quotidiani ai principi della dinamica.</p><div class="card-bottom"><span>3 capitoli · 3 laboratori · 9 esercizi</span><span class="arrow" style="color:var(--green)">↗</span></div></div></a></div><div class="method"><div><span class="number">01 / COMPRENDI</span><h3>Parti dall’idea.</h3><p>Ogni formula nasce da un ragionamento, spiegato con parole semplici.</p></div><div><span class="number">02 / ESPLORA</span><h3>Metti le mani nei concetti.</h3><p>Cambia un valore e osserva come cambia il grafico. L’intuizione prende forma.</p></div><div><span class="number">03 / METTITI ALLA PROVA</span><h3>Fai il passo successivo.</h3><p>Esercizi di tre livelli, con soluzioni commentate e una verifica immediata.</p></div></div><div class="intro-note"><span class="intro-symbol">∴</span><div><h3>Il rigore può parlare a tutti.</h3><p>Un sito didattico del Dottore in Ingegneria Federico Ennio Ambrogi,<br>pensato per studenti delle superiori e dell’università.</p></div><a href="#progetto">La storia di Proofly ↗</a></div></div>`}
function catalog(s){const ls=LESSONS.filter(l=>l.subject===s);return `<div class="container"><div class="catalog-head"><div class="breadcrumb"><a href="#home">Home</a> / ${subjectName(s)}</div><div class="eyebrow">${s==='fisica'?'Meccanica classica':'Geometria analitica'}</div><h1>${s==='fisica'?'I principi della dinamica.':'La retta nel piano.'}</h1><p>${s==='fisica'?'Un percorso in tre capitoli per capire il rapporto tra forze e moto, con ipotesi esplicite ed esempi concreti.':'Un percorso completo: dalle coordinate ai vettori, passando per equazioni, intersezioni, distanze e fasci.'}</p><span class="status">${ls.filter(l=>completed.has(l.id)).length} di ${ls.length} capitoli completati su questo dispositivo</span></div><div class="catalog-list">${ls.map((l,i)=>`<a class="catalog-row" href="#lezione/${l.id}"><span class="chapter-number">${completed.has(l.id)?'✓':String(i+1).padStart(2,'0')}</span><div><h2>${l.title}</h2><p>${l.description}</p></div><span class="meta">Laboratorio + 3 esercizi</span><span class="arrow">→</span></a>`).join('')}</div></div>`}
function about(){return `<article class="about"><div class="eyebrow">Il progetto</div><h1>Capire è per tutti.</h1><p class="lead">Proofly nasce da un’idea semplice: rendere matematica e fisica accessibili, senza rinunciare alla precisione.</p><div class="author"><div class="avatar">FA</div><div><h3>Federico Ennio Ambrogi</h3><p>Dottore in Ingegneria · Autore del progetto didattico Proofly</p><p>Un luogo dove una buona domanda diventa un percorso di comprensione.</p></div></div><h2>Semplice nelle parole. Serio nel metodo.</h2><p>Una spiegazione chiara non salta i passaggi importanti. Parte dall’intuizione, definisce i termini, rende esplicite le ipotesi e mostra perché una formula funziona. Su Proofly puoi seguire quel filo con il tuo ritmo.</p><p>Il sito è pensato sia per chi frequenta le superiori sia per gli studenti universitari che vogliono consolidare le basi. I richiami a vettori, prodotti scalari e quantità di moto offrono un ponte verso gli studi successivi.</p><h2>Dalla lettura alla scoperta.</h2><p>Ogni capitolo unisce teoria, un laboratorio interattivo ed esercizi svolti di livello base, intermedio e avanzato. Prova prima da solo, poi apri la soluzione e confronta il ragionamento, non soltanto il risultato.</p><h2>La prima tappa.</h2><p>Il percorso di matematica esplora la retta nel piano cartesiano. Quello di fisica presenta i tre principi della dinamica classica. Puoi cercare direttamente un concetto dalla home oppure seguire i capitoli in ordine.</p><div class="callout"><strong>I tuoi progressi, sul tuo dispositivo</strong>Il tema e i capitoli completati vengono salvati soltanto nel browser tramite memoria locale. Non servono un account o dati personali per studiare. Cancellando i dati del browser, i progressi vengono rimossi.</div><a class="btn" href="#home">Inizia da una domanda →</a></article>`}
function lesson(l){const ls=LESSONS.filter(x=>x.subject===l.subject),i=ls.indexOf(l),next=ls[i+1];return `<div class="lesson-layout"><aside class="sidebar"><a class="back" href="#materia/${l.subject}">← Tutti i capitoli</a><div class="sidebar-title">${subjectName(l.subject)} · Il percorso</div>${ls.map((x,j)=>`<a class="chapter ${x===l?'current':''}" ${x===l?'aria-current="page"':''} href="#lezione/${x.id}">${String(j+1).padStart(2,'0')} &nbsp; ${x.title}</a>`).join('')}</aside><article><header class="lesson-header"><div class="breadcrumb"><a href="#home">Home</a> / <a href="#materia/${l.subject}">${subjectName(l.subject)}</a> / Capitolo ${i+1}</div><span class="tag ${l.subject}">${l.subject==='fisica'?'Meccanica classica':'Geometria analitica'}</span><h1>${l.title}</h1><p class="lead">${l.description}</p><div class="lesson-meta"><span>Capitolo ${i+1} di ${ls.length}</span><span>1 laboratorio interattivo</span><span>3 esercizi svolti</span></div></header><nav class="toc" aria-label="In questo capitolo"><a href="#teoria" data-scroll="teoria">La spiegazione</a><a href="#laboratorio" data-scroll="laboratorio">Esplora il concetto</a><a href="#esercizi" data-scroll="esercizi">Esercizi e verifica</a></nav><div class="lesson-body" id="teoria">${l.sections.map(s=>`<section><h2>${s.title}</h2>${s.html}</section>`).join('')}<section id="laboratorio"><h2>Adesso, esplora tu.</h2><div class="lab" id="lab"><div class="lab-header"><span>Laboratorio interattivo</span></div><div class="lab-body" id="lab-body"></div></div></section><section class="exercises" id="esercizi"><div class="eyebrow">Dall’idea alla pratica</div><h2>Esercizi svolti</h2><p>Leggi il problema e prova a risolverlo prima di aprire lo svolgimento. Ogni livello aggiunge un passo al ragionamento.</p><div class="exercise-filter" role="group" aria-label="Filtra per difficoltà">${['tutti','base','intermedio','avanzato'].map((x,j)=>`<button class="chip ${j===0?'selected':''}" data-level="${x}" aria-pressed="${j===0}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>${l.exercises.map((e,j)=>`<div class="exercise" data-exercise="${e.level}"><span class="level ${e.level==='avanzato'?'hard':e.level==='intermedio'?'medium':''}">${e.level} · Esercizio ${j+1}</span><h3>${e.title}</h3><p>${e.question}</p><details><summary>Mostra lo svolgimento</summary><div class="solution">${e.solution}</div></details></div>`).join('')}<div class="check"><h3>Una verifica veloce.</h3><p>${l.check.question}</p><form id="check-form"><label class="hidden" for="answer">La tua risposta numerica</label><input id="answer" type="text" inputmode="decimal" aria-label="La tua risposta numerica" placeholder="La tua risposta" required><button class="btn" type="submit">Verifica</button></form><div class="feedback" id="feedback" role="status" aria-live="polite"></div><small style="color:var(--muted)">Puoi scrivere un numero decimale o una frazione, per esempio −1/4.</small></div></section></div><div class="lesson-end"><button id="complete" class="btn secondary">${completed.has(l.id)?'✓ Capitolo completato':'Segna come completato'}</button>${next?`<a href="#lezione/${next.id}">Prossimo: ${next.title} →</a>`:`<a href="#materia/${l.subject}">Torna al percorso →</a>`}</div></article></div>`}
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function search(q){const tokens=normalize(q).split(/\s+/).filter(Boolean);if(!tokens.length)return[];return LESSONS.map(l=>{const text=normalize(l.title+' '+l.description+' '+l.keywords+' '+l.subject+' '+l.sections.map(s=>s.title+' '+s.html.replace(/<[^>]+>/g,' ')).join(' '));const match=tokens.every(t=>text.includes(t));return{l,match,score:tokens.reduce((a,t)=>a+(normalize(l.title).includes(t)?3:normalize(l.keywords).includes(t)?2:1),0)}}).filter(x=>x.match).sort((a,b)=>b.score-a.score).map(x=>x.l)}
function route(){stopLab();stopLab=()=>{};const parts=location.hash.slice(1).split('/'),[page,id]=parts;let html;if(page==='lezione'){const l=LESSONS.find(l=>l.id===id);if(l){html=lesson(l);document.title=l.title+' — Proofly'}else{html='<div class="about"><h1>Questo capitolo non esiste.</h1><a href="#home">Torna alla home →</a></div>'}}else if(page==='materia'&&['matematica','fisica'].includes(id)){html=catalog(id);document.title=subjectName(id)+' — Proofly'}else if(page==='progetto'){html=about();document.title='Il progetto — Proofly'}else{html=home();document.title='Proofly — Capire, un passo alla volta.'}$('#main').innerHTML=html;$$('.header nav a').forEach(a=>a.classList.toggle('active',a.hash===`#materia/${page==='lezione'?LESSONS.find(l=>l.id===id)?.subject:id}`||a.hash===`#${page}`));math($('#main'));window.scrollTo(0,0);
if($('#search')){$('#search').addEventListener('input',e=>{const q=e.target.value.trim(),r=$('#results');r.className=q?'search-results':'hidden';if(q){const ls=search(q);r.innerHTML=ls.length?`<div class="empty" style="padding:8px 18px;font-size:11px">${ls.length} ${ls.length===1?'argomento trovato':'argomenti trovati'}</div>`+ls.map(l=>`<a class="search-result" href="#lezione/${l.id}">${l.title}<small>${subjectName(l.subject)} · ${l.description}</small></a>`).join(''):'<div class="empty">Nessun argomento trovato. Prova “retta”, “distanza”, “forza” o “Newton”.</div>'}});$('#search').addEventListener('keydown',e=>{if(e.key==='Enter'){const a=$('.search-result');if(a)a.click()}if(e.key==='Escape'){$('#search').value='';$('#results').className='hidden'}})}
if(page==='lezione'){const l=LESSONS.find(l=>l.id===id);if(!l)return;initLab(l.widget);$$('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();$('#'+a.dataset.scroll).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});$$('[data-level]').forEach(b=>b.onclick=()=>{$$('[data-level]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$$('[data-exercise]').forEach(x=>x.classList.toggle('hidden',b.dataset.level!=='tutti'&&x.dataset.exercise!==b.dataset.level))});$('#check-form').onsubmit=e=>{e.preventDefault();let val=$('#answer').value.trim().replace(/−/g,'-').replace(/,/g,'.');const bits=val.split('/');let n=NaN;if(bits.length===1&&val!=='')n=Number(val);if(bits.length===2&&bits.every(x=>x.trim()!==''&&Number.isFinite(Number(x)))&&Number(bits[1])!==0)n=Number(bits[0])/Number(bits[1]);const correct=Number.isFinite(n)&&Math.abs(n-l.check.answer)<.001;$('#feedback').style.color=correct?'var(--green)':'var(--muted)';$('#feedback').textContent=!Number.isFinite(n)?'Inserisci un numero valido o una frazione con denominatore diverso da zero.':correct?'Corretto! '+l.check.explanation:'Riprova: rileggi i dati, scegli la formula e controlla i segni.'};$('#complete').onclick=()=>{if(completed.has(id))completed.delete(id);else completed.add(id);save('proofly-completed',[...completed]);$('#complete').textContent=completed.has(id)?'✓ Capitolo completato':'Segna come completato'}}}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()};
window.addEventListener('hashchange',route);document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&$('#search')){e.preventDefault();$('#search').focus()}});
/* Grafici geometrici con la stessa scala sui due assi. */
function geometry({lines=[],points=[],segments=[],triangle=false}){const W=600,H=340,extent=Math.max(6,...points.flatMap(p=>[Math.abs(p.x),Math.abs(p.y)])),scale=(H/2-32)/extent,X=x=>W/2+x*scale,Y=y=>H/2-y*scale,xmax=(W/2-20)/scale,ymax=(H/2-20)/scale,step=extent>12?5:extent>7?2:1;let out=`<svg class="plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="Grafico cartesiano con rette e punti; i valori sono descritti sotto il grafico"><defs><clipPath id="graphclip"><rect x="20" y="20" width="560" height="300"/></clipPath></defs>`;for(let x=-Math.floor(xmax/step)*step;x<=xmax;x+=step){out+=`<path d="M${X(x)} 20V320" stroke="var(--grid)"/>`;if(x!==0)out+=`<text x="${X(x)}" y="${H/2+16}" text-anchor="middle">${fmt(x)}</text>`}for(let y=-Math.floor(ymax/step)*step;y<=ymax;y+=step){out+=`<path d="M20 ${Y(y)}H580" stroke="var(--grid)"/>`;if(y!==0)out+=`<text x="${W/2-9}" y="${Y(y)+4}" text-anchor="end">${fmt(y)}</text>`}out+=`<path d="M20 ${H/2}H580M${W/2} 20V320" stroke="var(--muted)" opacity=".55"/><text x="586" y="${H/2-7}">x</text><text x="${W/2+9}" y="17">y</text><text x="${W/2-13}" y="${H/2+16}">0</text><g clip-path="url(#graphclip)">`;for(const l of lines){const norm=Math.hypot(l.a,l.b);if(norm<1e-10)continue;const px=-l.a*l.c/(norm*norm),py=-l.b*l.c/(norm*norm),dx=l.b/norm*1000,dy=-l.a/norm*1000;out+=`<path d="M${X(px-dx)} ${Y(py-dy)}L${X(px+dx)} ${Y(py+dy)}" stroke="${l.color||'var(--blue)'}" stroke-width="2.5" fill="none"/>`}for(const s of segments){out+=`<path d="M${X(s.x1)} ${Y(s.y1)}L${X(s.x2)} ${Y(s.y2)}" stroke="${s.color||'var(--violet)'}" stroke-width="2" stroke-dasharray="${s.dash||'5 4'}"/>`}if(triangle&&points.length>=2){const[a,b]=points;out+=`<path d="M${X(a.x)} ${Y(a.y)}H${X(b.x)}V${Y(b.y)}" stroke="var(--green)" stroke-width="1.8" stroke-dasharray="4 4" fill="none"/>`}for(const p of points){out+=`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="5" fill="${p.color||'var(--blue)'}" stroke="var(--bg)" stroke-width="2"/><text x="${X(p.x)+9}" y="${Y(p.y)-9}">${esc(p.name)} (${fmt(p.x)}; ${fmt(p.y)})</text>`}return out+'</g></svg>'}
function timeplot(a,v,t){const W=600,H=270,left=52,top=20,right=22,bottom=40,T=5,values=Array.from({length:101},(_,i)=>v*i*T/100+.5*a*(i*T/100)**2),low=Math.min(0,...values),high=Math.max(0,...values),span=Math.max(1,high-low),ymin=low-span*.12,ymax=high+span*.12,X=x=>left+x/T*(W-left-right),Y=y=>H-bottom-(y-ymin)/(ymax-ymin)*(H-top-bottom);let out=`<svg class="plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="Grafico della posizione in funzione del tempo da zero a cinque secondi"><path d="M${left} ${top}V${H-bottom}H${W-right}" stroke="var(--muted)" fill="none"/>`;for(let i=0;i<=5;i++){out+=`<path d="M${X(i)} ${top}V${H-bottom}" stroke="var(--grid)"/><text x="${X(i)}" y="${H-bottom+18}" text-anchor="middle">${i}</text>`}for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;out+=`<path d="M${left} ${Y(y)}H${W-right}" stroke="var(--grid)"/><text x="${left-7}" y="${Y(y)+4}" text-anchor="end">${fmt(y)}</text>`}out+=`<path d="${values.map((y,i)=>(i===0?'M':'L')+X(i*T/100)+' '+Y(y)).join(' ')}" fill="none" stroke="var(--blue)" stroke-width="2.5"/><circle cx="${X(t)}" cy="${Y(v*t+.5*a*t*t)}" r="5" fill="var(--blue)"/><text x="${W-50}" y="${H-5}">t (s)</text><text x="${left+5}" y="15">x (m)</text></svg>`;return out}
const cfg={
line:{description:'Muovi pendenza e intercetta. Osserva il punto (0,q) e come la retta cambia direzione.',controls:[['m','Pendenza m',-4,4,.25,1],['q','Intercetta q',-4,4,.5,1]]},
implicit:{description:'Varia i coefficienti di ax + by + c = 0. Prova b = 0 per una verticale e a = b = 0 per una degenerazione.',controls:[['a','Coefficiente a',-4,4,1,2],['b','Coefficiente b',-4,4,1,3],['c','Termine c',-6,6,1,-6]]},
slope:{description:'Cambia le coordinate dei due punti. Il triangolo tratteggiato mostra Δx e Δy.',controls:[['x1','Ascissa di A',-5,5,1,-2],['y1','Ordinata di A',-5,5,1,-1],['x2','Ascissa di B',-5,5,1,3],['y2','Ordinata di B',-5,5,1,4]]},
two:{description:'Scegli due punti. Il laboratorio calcola la retta e riconosce punti coincidenti e rette verticali.',controls:[['x1','Ascissa di A',-5,5,1,1],['y1','Ordinata di A',-5,5,1,2],['x2','Ascissa di B',-5,5,1,3],['y2','Ordinata di B',-6,6,1,6]]},
point:{description:'Scegli P e la pendenza: la retta resta ancorata al punto mentre cambia direzione.',controls:[['x0','Ascissa di P',-5,5,1,2],['y0','Ordinata di P',-5,5,1,-1],['m','Pendenza m',-4,4,.25,2]]},
relations:{description:'La retta blu è y = mx + q. La parallela verde e la perpendicolare viola passano per P.',controls:[['m','Pendenza di r',-4,4,.25,2],['q','Intercetta di r',-4,4,.5,1],['x0','Ascissa di P',-4,4,1,1],['y0','Ordinata di P',-4,4,1,3]]},
intersection:{description:'Varia le due rette. Prova pendenze uguali e poi intercette uguali per distinguere i tre casi.',controls:[['m1','Pendenza di r',-3,3,.5,1],['q1','Intercetta di r',-4,4,.5,1],['m2','Pendenza di s',-3,3,.5,-1],['q2','Intercetta di s',-4,4,.5,3]]},
distance:{description:'Muovi P e la retta. Il segmento viola collega il punto al piede H della perpendicolare.',controls:[['x0','Ascissa di P',-5,5,1,2],['y0','Ordinata di P',-5,5,1,4],['m','Pendenza di r',-3,3,.5,1],['q','Intercetta di r',-4,4,.5,-1]]},
family:{description:'Le rette grigie e blu passano tutte per il centro C. La verticale tratteggiata completa il fascio.',controls:[['x0','Ascissa del centro',-3,3,1,1],['y0','Ordinata del centro',-3,3,1,2],['m','Parametro k',-4,4,.25,1]]},
parametric:{description:'Il punto Q = P + t·v si muove sulla retta. Cambia il vettore direttore; il vettore nullo non dà una retta.',controls:[['u','Componente u',-3,3,1,2],['v','Componente v',-3,3,1,1],['t','Parametro t',-2,2,.1,1]]},
inertia:{description:'Moto in una dimensione senza attrito e con risultante orizzontale nulla. Posizione iniziale x₀ = 0.',controls:[['v0','Velocità iniziale (m/s)',-5,5,.5,2],['t','Tempo (s)',0,5,.1,0]]},
newton:{description:'Massa costante, forza risultante orizzontale costante, nessun attrito; x₀ = 0 e v₀ = 0. Il segno di F sceglie il verso.',controls:[['F','Forza risultante (N)',-20,20,1,10],['mass','Massa (kg)',1,10,.5,2],['t','Tempo (s)',0,5,.1,0]]},
action:{description:'Due carrelli inizialmente fermi, senza forze esterne orizzontali. La spinta interna ha intensità F costante.',controls:[['F','Intensità della spinta (N)',0,20,1,10],['massA','Massa di A (kg)',1,10,.5,2],['massB','Massa di B (kg)',1,10,.5,5],['t','Durata della spinta (s)',0,2,.1,1]]}
};
function initLab(type){const c=cfg[type],values=Object.fromEntries(c.controls.map(x=>[x[0],x[5]]));$('#lab-body').innerHTML=`<p class="lab-description">${c.description}</p><div class="lab-controls">${c.controls.map(([key,label,min,max,step,value])=>`<div class="control"><label for="lab-${key}">${label}<output id="out-${key}">${fmt(value)}</output></label><input id="lab-${key}" data-key="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`).join('')}</div><div id="lab-display"></div>${['inertia','newton'].includes(type)?'<div class="sim-actions"><button id="play" class="btn">Avvia</button><button id="reset" class="btn secondary">Ricomincia</button></div>':''}`;let frame=0,playing=false,last=0;const update=()=>{$('#lab-display').innerHTML=drawLab(type,values);c.controls.forEach(([k])=>$('#out-'+k).textContent=fmt(values[k]))};$$('[data-key]').forEach(input=>input.oninput=()=>{values[input.dataset.key]=Number(input.value);update()});if($('#play')){const halt=()=>{playing=false;cancelAnimationFrame(frame);const playButton=$('#play');if(playButton)playButton.textContent='Avvia'};stopLab=halt;$('#play').onclick=()=>{if(playing){halt();return}if(values.t>=5)values.t=0;playing=true;last=performance.now();$('#play').textContent='Pausa';const tick=now=>{if(!playing)return;values.t=Math.min(5,values.t+(now-last)/1000);last=now;$('#lab-t').value=values.t;update();if(values.t>=5)halt();else frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick)};$('#reset').onclick=()=>{halt();values.t=0;$('#lab-t').value=0;update()}}else stopLab=()=>{};update()}
function drawLab(type,z){let lines=[],points=[],segments=[],text='',legend='',triangle=false;const line=(m,q,color)=>({a:m,b:-1,c:q,color});const result=html=>`<div class="lab-result" aria-live="polite">${html}<small style="color:var(--muted);font-size:10px">Valori calcolati arrotondati a tre decimali. I grafici geometrici usano scale uguali sui due assi.</small></div>`;
if(type==='line'){lines=[line(z.m,z.q)];points=[{x:0,y:z.q,name:'Q'}];text=fm(eq(z.m,z.q))+`<p>Per +1 in x, y varia di ${fmt(z.m)}. La retta è ${z.m===0?'orizzontale':z.m>0?'crescente':'decrescente'}.</p>`}
if(type==='implicit'){lines=[{a:z.a,b:z.b,c:z.c}];if(z.a===0&&z.b===0)text=z.c===0?'0 = 0: ogni punto del piano soddisfa l’equazione. Non è una retta.':'L’equazione è impossibile: insieme vuoto. Non è una retta.';else text=fm(`${z.a}x+(${z.b})y+(${z.c})=0`)+`<p>${z.b===0?fm('x='+texnum(-z.c/z.a))+' · retta verticale':fm(eq(-z.a/z.b,-z.c/z.b))+' · forma esplicita'}</p>`}
if(type==='slope'||type==='two'){const dx=z.x2-z.x1,dy=z.y2-z.y1;points=[{x:z.x1,y:z.y1,name:'A'},{x:z.x2,y:z.y2,name:'B',color:'var(--green)'}];triangle=type==='slope';lines=[{a:dy,b:-dx,c:dx*z.y1-dy*z.x1}];if(dx===0&&dy===0)text='A e B coincidono: infinite rette passano per questo punto. Serve un’altra informazione.';else if(dx===0)text=fm('x='+z.x1)+'<p>Retta verticale: Δx = 0, quindi m non è definito.</p>';else{const m=dy/dx;text=fm(`m=\\frac{${dy}}{${dx}}=${texnum(m)}`)+'<p>'+fm(eq(m,z.y1-m*z.x1))+` · Δx = ${fmt(dx)}, Δy = ${fmt(dy)}.</p>`}}
if(type==='point'){lines=[line(z.m,z.y0-z.m*z.x0)];points=[{x:z.x0,y:z.y0,name:'P'}];text=fm(`y-(${z.y0})=${texnum(z.m)}(x-(${z.x0}))`)+`<p>${fm(eq(z.m,z.y0-z.m*z.x0))}</p>`}
if(type==='relations'){const qpar=z.y0-z.m*z.x0;lines=[line(z.m,z.q),line(z.m,qpar,'var(--green)')];if(z.m===0){lines.push({a:1,b:0,c:-z.x0,color:'var(--violet)'});text='r è orizzontale. La perpendicolare è '+fm('x='+z.x0)}else{const mp=-1/z.m;lines.push(line(mp,z.y0-mp*z.x0,'var(--violet)'));text='Perpendicolare: '+fm(eq(mp,z.y0-mp*z.x0))+`<p>${fm('m_r\\,m_\\perp=-1')}</p>`}points=[{x:z.x0,y:z.y0,name:'P',color:'var(--violet)'}];text+=`<p>Parallela: ${fm(eq(z.m,qpar))}${Math.abs(qpar-z.q)<1e-9?' · coincide con r.':''}</p>`;legend='<span><i style="background:var(--blue)"></i>Retta r</span><span><i style="background:var(--green)"></i>Parallela</span><span><i style="background:var(--violet)"></i>Perpendicolare</span>'}
if(type==='intersection'){lines=[line(z.m1,z.q1),line(z.m2,z.q2,'var(--green)')];if(z.m1===z.m2)text=z.q1===z.q2?'Rette coincidenti: infiniti punti in comune.':'Rette parallele distinte: nessun punto in comune.';else{const x=(z.q2-z.q1)/(z.m1-z.m2),y=z.m1*x+z.q1;points=[{x,y,name:'P'}];text='Rette incidenti: '+fm(`P=(${texnum(x)},${texnum(y)})`)}text+=`<p>r: ${fm(eq(z.m1,z.q1))} &nbsp; s: ${fm(eq(z.m2,z.q2))}</p>`;legend='<span><i style="background:var(--blue)"></i>r</span><span><i style="background:var(--green)"></i>s</span>'}
if(type==='distance'){const a=z.m,b=-1,c=z.q,s=a*z.x0+b*z.y0+c,n=a*a+b*b,hx=z.x0-a*s/n,hy=z.y0-b*s/n,d=Math.abs(s)/Math.sqrt(n);lines=[line(z.m,z.q)];points=[{x:z.x0,y:z.y0,name:'P'},{x:hx,y:hy,name:'H',color:'var(--violet)'}];segments=[{x1:z.x0,y1:z.y0,x2:hx,y2:hy}];text=fm(`d(P,r)=${texnum(d)}`)+`<p>P(${fmt(z.x0)}; ${fmt(z.y0)}), H(${fmt(hx)}; ${fmt(hy)}). ${d<1e-9?'P appartiene alla retta.':'PH è perpendicolare alla retta.'}</p>`}
if(type==='family'){lines=[-2,-1,0,1,2].map(m=>line(m,z.y0-m*z.x0,'var(--line)'));lines.push(line(z.m,z.y0-z.m*z.x0));points=[{x:z.x0,y:z.y0,name:'C'}];segments=[{x1:z.x0,y1:-6,x2:z.x0,y2:6,color:'var(--violet)'}];text=fm(`y-(${z.y0})=${texnum(z.m)}(x-(${z.x0}))`)+`<p>Tutti i membri passano per C. La verticale ${fm('x='+z.x0)} completa il fascio.</p>`}
if(type==='parametric'){const x0=1,y0=1;lines=[{a:-z.v,b:z.u,c:z.v*x0-z.u*y0}];points=[{x:x0,y:y0,name:'P'},{x:x0+z.t*z.u,y:y0+z.t*z.v,name:'Q',color:'var(--green)'}];text=z.u===0&&z.v===0?'Vettore nullo: Q coincide sempre con P. Non è una retta.':fm(`Q=(${texnum(x0+z.t*z.u)},${texnum(y0+z.t*z.v)})`)+`<p>${fm('x=1+t\\,('+z.u+'),\\quad y=1+t\\,('+z.v+')')}.</p>`}
if(type==='inertia'||type==='newton'){const a=type==='newton'?z.F/z.mass:0,v0=type==='inertia'?z.v0:0,v=v0+a*z.t,x=v0*z.t+.5*a*z.t*z.t;return timeplot(a,v0,z.t)+result(`${fm(`a=${texnum(a)}\\,\\mathrm{m/s^2},\\quad v=${texnum(v)}\\,\\mathrm{m/s}`)}<p>t = ${fmt(z.t)} s · x = ${fmt(x)} m. ${type==='inertia'?'La velocità resta costante.':'La risultante modifica la velocità.'}</p>`)}
if(type==='action'){const aa=-z.F/z.massA,ab=z.F/z.massB,xA=.5*aa*z.t*z.t,xB=.5*ab*z.t*z.t,range=Math.max(2,Math.abs(xA),Math.abs(xB)),scale=150/range,xa=230+xA*scale,xb=370+xB*scale,forceLength=z.F*2;return `<svg class="plot" viewBox="0 0 600 220" role="img" aria-label="Due carrelli con forze uguali e opposte: A accelera a sinistra, B a destra"><path d="M25 155H575" stroke="var(--line)"/><rect x="${xa-23}" y="95" width="46" height="38" rx="5" fill="var(--blue)"/><rect x="${xb-23}" y="95" width="46" height="38" rx="5" fill="var(--green)"/><text x="${xa}" y="84" text-anchor="middle">A · ${fmt(z.massA)} kg</text><text x="${xb}" y="84" text-anchor="middle">B · ${fmt(z.massB)} kg</text>${z.F>0?`<path d="M${xa-27} 112h-${forceLength}m7-5-7 5 7 5" stroke="var(--blue)" stroke-width="2" fill="none"/><path d="M${xb+27} 112h${forceLength}m-7-5 7 5-7 5" stroke="var(--green)" stroke-width="2" fill="none"/>`:''}<text x="300" y="185" text-anchor="middle">Forze uguali in modulo, accelerazioni dipendenti dalle masse</text></svg>`+result(`${fm(`F_{B\\to A}=-${z.F}\\,\\mathrm N,\\quad F_{A\\to B}=+${z.F}\\,\\mathrm N`)}<p>aA = ${fmt(aa)} m/s² · aB = ${fmt(ab)} m/s².</p><p>Da t = 0, spostamenti: ΔxA = ${fmt(xA)} m · ΔxB = ${fmt(xB)} m. Le posizioni iniziali sono separate nello schema per rendere leggibili le frecce.</p>`)}
return geometry({lines,points,segments,triangle})+(legend?`<div class="legend">${legend}</div>`:'')+result(text)}
route();
